const mongoose = require('mongoose');

const userSchema = new mongoose.Schema({
  name: { type: String, required: true, trim: true },
  // Internal reference generated by the API; admins do not enter it.
  employeeId: { type: String, required: true, unique: true, uppercase: true, trim: true },
  email: { type: String, lowercase: true, trim: true, sparse: true, unique: true, required: function () { return this.isNew; } },
  phone: { type: String, trim: true, default: '' },
  isDeleted: { type: Boolean, default: false },
  deletedAt: { type: Date, default: null },
  passwordHash: { type: String, required: true, select: false },
  role: { type: String, enum: ['admin', 'employee'], default: 'employee', required: true },
  active: { type: Boolean, default: true }
}, { timestamps: true });

module.exports = mongoose.model('User', userSchema);
